#include <bits/stdc++.h>
using namespace std;
using ll = long long;

const int MOD = 1e9 + 7;

int add_mod(int a, int b) {
    int res = a + b;
    if (res >= MOD) res -= MOD;
    return res;
}

int sub_mod(int a, int b) {
    int res = a - b;
    if (res < 0) res += MOD;
    return res;
}

int mul_mod(int a, int b) {
    return (int)((1LL * a * b) % MOD);
}

ll n;
int k;

vector<vector<int>> mat_mult(const vector<vector<int>>& A, const vector<vector<int>>& B) {
    vector<vector<int>> C(k + 1, vector<int>(k + 1, 0));
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= k; j++) {
            for (int t = 0; t <= k; t++) {
                C[i][t] = add_mod(C[i][t], mul_mod(A[i][j], B[j][t]));
            }
        }
    }
    return C;
}

vector<vector<int>> pref[100];

vector<vector<int>> shift_matrix(const vector<vector<int>>& M) {
    vector<vector<int>> res(k + 1, vector<int>(k + 1, 0));
    for (int i = 0; i <= k; i++) {
        for (int j = 0; j <= k; j++) {
            int ni = i;
            if (ni < k) ni = (ni + k - 1) % k;
            int nj = j;
            if (nj < k) nj = (nj + k - 1) % k;
            res[i][j] = M[ni][nj];
        }
    }
    return res;
}

void prepare() {
    ll temp = n;
    int digits = 0;
    while (temp > 0) {
        temp /= k;
        digits++;
    }
    pref[0].resize(k + 1, vector<int>(k + 1, 0));
    for (int i = 1; i < k; i++) {
        pref[0][i][i] = 1;
    }
    pref[0][0][k] = 1;
    pref[0][k][0] = MOD - 1;
    pref[0][k][k] = 2;

    for (int s = 0; s < digits; s++) {
        pref[s + 1] = pref[s];
        auto current = pref[s];
        for (int i = 1; i <= k - 1; i++) {
            current = shift_matrix(current);
            pref[s + 1] = mat_mult(pref[s + 1], current);
        }
    }
}

vector<vector<int>> get_result(ll n_value) {
    if (n_value == 0) {
        vector<vector<int>> c(k + 1, vector<int>(k + 1, 0));
        for (int i = 0; i <= k; i++) c[i][i] = 1;
        return c;
    }
    ll pw = 1;
    int d = 0;
    while (pw <= n_value / k) {
        pw *= k;
        d++;
    }
    if (n_value == pw) return pref[d];
    ll steps = n_value / pw;
    ll rem = n_value - steps * pw;
    auto matrix_curr = prepare();
    auto coef = pref[d];
    for (int i = 0; i < steps; i++) {
        matrix_curr = mat_mult(matrix_curr, coef);
        coef = shift_matrix(coef);
    }
    auto remaining = prepare();
    for (int i = 0; i < steps; i++) {
        remaining = shift_matrix(remaining);
    }
    return mat_mult(matrix_curr, remaining);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> n >> k;
    prepare();
    auto answer = get_result(n);
    cout << answer[k][k];
    return 0;
}
